// Designer Loop — review code_review queue every 30 min
// Picks 1 issue at a time where designer_status=pending
const SK = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InR3dGhnYXBpb3VpcWhhdnJjbnJ5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NDUzMTY3NiwiZXhwIjoyMDkwMTA3Njc2fQ.EyNdtvECdcHx3RuaizdfLGNRY4OJotzjE2QeOQ9Yf4Q';
const SUPA = 'https://twthgapiouiqhavrcnry.supabase.co';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const TRIGGER_URL = 'http://127.0.0.1:8787/trigger-agent';

const issues = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=eq.code_review&designer_status=eq.pending&select=id,task_key,title,description,acceptance_criteria,implementation_notes,commit_sha,feature_branch,pr_url,type,project,severity&limit=1&order=created_at.asc',
  headers: h
});
if (!Array.isArray(issues) || !issues.length) return [{ json: { action: 'idle', queue: 0 } }];

const issue = issues[0];
const prompt = [
  'You are Designer. Review this issue for UI/UX quality. Check against your SOUL.md review checklist.',
  '',
  '## ' + issue.task_key + ' — ' + issue.title,
  'Type: ' + issue.type + ' | Project: ' + issue.project + ' | Severity: ' + (issue.severity || 'not set — treat as S1'),
  '',
  'Review depth for ' + (issue.severity || 'S1') + ':',
  '- S0: Full design audit (typography, spacing, color, mobile, accessibility)',
  '- S1: Functional UI check (layout correct, no broken elements, mobile works)',
  '- S2: Quick pass (nothing visually broken)',
  '- S3: Sanity check only',
  '',
  '## Acceptance Criteria',
  issue.acceptance_criteria || '(not set)',
  '',
  '## Implementation Notes',
  issue.implementation_notes || '(not set)',
  '',
  '## References',
  'commit_sha: ' + (issue.commit_sha || 'none') + ' | branch: ' + (issue.feature_branch || 'none') + ' | pr: ' + (issue.pr_url || 'none'),
  '',
  '## Action Required',
  'PASS → PATCH http://localhost:3000/api/issues:',
  '  {"id": "' + issue.id + '", "designer_status": "passed", "designer_notes": "<summary>", "transitioned_by": "designer"}',
  '',
  'FAIL → PATCH:',
  '  {"id": "' + issue.id + '", "designer_status": "failed", "designer_notes": "<what failed>", "transitioned_by": "designer"}',
  '',
  'After completing, check for more: GET ' + SUPA + '/rest/v1/issues?status=eq.code_review&designer_status=eq.pending&limit=1&order=created_at.asc',
].join('\n');

try {
  await helpers.httpRequest({
    method: 'POST', url: TRIGGER_URL,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ agentId: 'designer', message: prompt })
  });
  return [{ json: { action: 'designer_triggered', task: issue.task_key, severity: issue.severity } }];
} catch(e) {
  return [{ json: { action: 'error', message: e.message } }];
}
